  expect(gitRun(c.remote, 'cat-file', 'blob', D + ':accord/tickets/ST-10.md')).toBe(
    crlf.replace('status: open', 'status: "dropped"') + '\r\n## Dropped\r\nno longer needed\r\n',
  );
