it('risk:complex-branching pick up refuses a ticket that origin main lacks', async () => {
  const c = clone();
  writeFiles(c.root, { 'accord/tickets/ST-30.md': laneTicket('ST-30') });
  const { code, err } = await run(['worktree', 'open', 'ST-30'], c.root);
